long[] leftToRight = new long[n];
        long[] rightToLeft = new long[n];

        for (int i = 0; i < n; i++) {
            leftToRight[i] = i;
            rightToLeft[i] = n - i - 1;
        }

        long collisions = 0;
        while (true) {
            for (int i = 0; i < n; i++) {
                if (leftToRight[i] == rightToLeft[i]) {
                    collisions++;
                }
                leftToRight[i]++;
                rightToLeft[i]--;
            }
            boolean allMoved = true;
            for (int i = 0; i < n; i++) {
                if (leftToRight[i] != i || rightToLeft[i] != n - i - 1) {
                    allMoved = false;
